import { VThemes } from "./VTheme";
var VButton = (function () {
    function VButton() {
    }
    VButton.create = function (id, label) {
        var btn = document.createElement("BUTTON");
        btn.id = id;
        btn.innerHTML = label;
        this.styleIt(btn);
        return btn;
    };
    VButton.styleIt = function (btn) {
        btn.classList.add("w3-btn");
        btn.style.color = VThemes.CurrentTheme.lightColors.f;
        btn.style.backgroundColor = VThemes.CurrentTheme.lightColors.b;
    };
    VButton.styleThem = function (btns) {
        var l = btns.length;
        for (var i = 0; i < l; i++) {
            VButton.styleIt(btns[i]);
        }
    };
    return VButton;
}());
export { VButton };
