import { VDiag } from "./components/VDiag";
var DialogMgr = (function () {
    function DialogMgr() {
    }
    DialogMgr.createAlertDiag = function () {
        if (this._alertDialog == null) {
            this._alertDiv = document.createElement("div");
            this._alertDiv.style.textAlign = "center";
            this._alertDiv.style.padding = "1em";
            this._alertDialog = new VDiag(this._alertDiv, "Info", VDiag.center, "", "", "12em");
        }
    };
    DialogMgr.showAlertDiag = function (msg) {
        if (this._alertDialog == null)
            DialogMgr.createAlertDiag();
        this._alertDiv.innerHTML = msg;
        this._alertDialog.open();
    };
    DialogMgr.vdiags = new Array();
    return DialogMgr;
}());
export { DialogMgr };
